u}\! \left(Xight) = 0$. The proof for $\operatorname{\mathcal{E}}_{\mu}\! \left(Wight)$ is the same.

Suppose $X, Y$ are centered in $\operatorname{VP}$. We begin by computing
\begin{align*}
\operatorname{cov}_{\mu_{\mathbf{G}}}\left( \partial^* X, \partial^* Y \right) 
= \operatorname{\mathcal{E}}_{\mu_{\mathbf{G}}}\! \left(\left< W, \partial^* X \right> \left< W, \partial^* Y \right>\right)
& = \int_{W \in \operatorname{ED}} \left< W, \partial^* X \right> \left< W, \partial^*Y \right> \mu_{\mathbf{G}}(dW) \\
& = \int_{W \in \operatorname{im} \partial^*} \left< W, \partial^* X \right> \left< W, \partial^*Y \right> \mu_{\mathbf{G}}(dW)
\end{align*}
since $\mu_{\mathbf{G}}$ is concentrated on $\operatorname{im} \partial^*$. Therefore, since $\mu_{\mathbf{G}} = (\partial^*)_\sharp \nu_{\mathbf{G}}$, this integral is equal to
\begin{align*}
\operatorname{cov}_{\mu_{\mathbf{G}}}\left( \partial^* X, \partial^* Y \right) 
&= \int_{Z \in \operatorname{VP}} \left< \partial^* Z, \partial^* X \right> \left< \partial^*Z, \partial^*Y \right> \nu_{\mathbf{G}}(dZ) \\
&= \int_{Z \in (\ker \partial^*)^\perp} \left< \partial^* Z, \partial^* X \right> \left< \partial^*Z, \partial^*Y \right> \nu_{\mathbf{G}}(dZ) \\
&= \int_{Z \in (\ker \partial^*)^\perp} \left< Z, X \right>_{\tilde{L}^*} \left< Z, Y \right>_{\tilde{L}^*} \nu_{\mathbf{G}}(dZ) = \operatorname{cov}_{\nu_{\mathbf{G}}}\left( X, Y \right).
\end{align*}
Here we have used the fact that $\nu_{\mathbf{G}}$ is supported on the centered configurations $(\ker \partial^*)^\perp$ in the second equality, and~Proposition~\ref{prop:bdystar is a partial isometry} in the third. 

The second half of the proof follows from the fact that $\nu_{\mathbf{G}}$ and $\mu_{\mathbf{G}}$ are concentrated on $(\ker \partial^*)^\perp$ and $\operatorname{im} \partial^*$. In general, if we have a random vector $x$ chosen according to a probability measure $\rho$ which is concentrated on a subspace $S$ of $\left( V, \left< -, - \right>_{V} \right)$, then for any $u \in S^\perp$, 
\begin{equation*}
\operatorname{cov}_{\rho}\left( u, v \right) = \int_{x \in V} \left< u, x \right>_{V} \left< v, x \right>_{V} \rho(dx) = \int_{x \in S} \left< u, x \right>_{V} \left< v, x \right>_{V} \rho(dx) = 0,
\end{equation*}
because we know that $\left< u, x \right>_{V} = 0$ since $x \in S$ and $u \in S^\perp$.

\label{cor:XXt and WWt}\ifinner\else\mgp{\raggedright\tiny \ref{cor:XXt and WWt} cor:XXt and WWt}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{cor:XXt and WWt} cor:XXt and WWt}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{cor:XXt and WWt} cor:XXt and WWt}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{cor:XXt and WWt} cor:XXt and WWt}\ignorespaces\fi
With the hypotheses of~Proposition~\ref{prop:matching covariances}, and the notation of~Proposition~\ref{prop:block structure of XXt} and~Proposition~\ref{prop:block structure of WWt}, we have $\partial^* \operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(XX^T\right) \partial^{*T} = \operatorname{\mathcal{E}}_{\mu_{\mathbf{G}}}\! \left(WW^T\right)$ and so $\partial^T \Sigma_\mathbf{v} \partial = \Sigma_\mathbf{e}$. Further, 
\begin{equation*}
\operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(XX^T\right) = \partial^{*+} \operatorname{\mathcal{E}}_{\mu_{\mathbf{G}}}\! \left(WW^T\right) \partial^{*T+} \quad\text{and}\quad \Sigma_\mathbf{v} = \partial^{T+} \Sigma_\mathbf{e} \partial^+.
\end{equation*}

Suppose $U, V \in \operatorname{VP}$ are centered. Then $\operatorname{cov}_{\nu_{\mathbf{G}}}\left( U, V \right) = \operatorname{cov}_{\mu_{\mathbf{G}}}\left( \partial^* U, \partial^* V \right)$. Using~\eqref{eq:covariance in general inner product},
\begin{equation*}
\operatorname{cov}_{\nu_{\mathbf{G}}}\left( U, V \right) 
= \operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(\left< X, U \right>_{\tilde{L}^*} \left< X, V \right>_{\tilde{L}^*}\right) 

= \left< \tilde{L}^* U, \operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(XX^T\right) \tilde{L}^* V \right>.
\end{equation*}
Using~Proposition~\ref{prop:centered} and $\tilde{L}^* = L^* + (\frac{1}{\mathbf{v}} \mathbf{1}_{\mathbf{v} \times \mathbf{v}})^*$, we have
$\tilde{L}^*U = L^* U$ and $\tilde{L}^* V = L^* V$. So
\begin{equation}
\begin{aligned}
\operatorname{cov}_{\nu_{\mathbf{G}}}\left( U, V \right) 
&= \left< L^* U, \operatorname{\mathcal{E}}_{\nu}\! \left(XX^T\right)L^* V \right> \\
&= \left< \partial^{T*} \partial^* U, \operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(XX^T\right)\partial^{*T} \partial^* V \right> \\
&= \left< \partial^* U, \partial^* \operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(XX^T\right) \partial^{*T} \partial^*V \right>
\end{aligned}
\label{eq:covariance in nu of U and V}\ifinner\else\mgp{\raggedright\tiny \ref{eq:covariance in nu of U and V} eq:covariance in nu of U and V}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{eq:covariance in nu of U and V} eq:covariance in nu of U and V}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{eq:covariance in nu of U and V} eq:covariance in nu of U and V}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{eq:covariance in nu of U and V} eq:covariance in nu of U and V}\ignorespaces\fi
\end{equation}
On the other hand, using~\eqref{eq:covariance in general inner product} and the fact that the dot product on $\left( \operatorname{ED}, \left< -, - \right> \right)$ is standard, 
\begin{equation}
\operatorname{cov}_{\mu_{\mathbf{G}}}\left( \partial^* U, \partial^* V \right) = \left< \partial^* U, \operatorname{\mathcal{E}}_{\mu_{\mathbf{G}}}\! \left(WW^T\right) \partial^* V \right>
\label{eq:covariance in mu of bdystar U and bdystar V}\ifinner\else\mgp{\raggedright\tiny \ref{eq:covariance in mu of bdystar U and bdystar V} eq:covariance in mu of bdystar U and bdystar V}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{eq:covariance in mu of bdystar U and bdystar V} eq:covariance in mu of bdystar U and bdystar V}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{eq:covariance in mu of bdystar U and bdystar V} eq:covariance in mu of bdystar U and bdystar V}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{eq:covariance in mu of bdystar U and bdystar V} eq:covariance in mu of bdystar U and bdystar V}\ignorespaces\fi
\end{equation}
We now have two matrices $\partial^* \operatorname{\mathcal{E}}_{\nu}\! \left(XX^T\right) \partial^{*T}$ and $\operatorname{\mathcal{E}}_{\mu}\! \left(WW^T\right)$. The kernel of each matrix contains the loop space $\ker \partial^{*T} = (\operatorname{im} \partial^*)^\perp$ in $\operatorname{ED}$. The image of each matrix is contained in $\operatorname{im} \partial^*$. Combining~\eqref{eq:covariance in nu of U and V} and~\eqref{eq:covariance in mu of bdystar U and bdystar V} and using the shared kernel, we have for all $Z \in \operatorname{im} \partial^*$ and $P \in \operatorname{ED}$ that
\begin{equation*}
\left< Z, \operatorname{\mathcal{E}}_{\mu_{\mathbf{G}}}\! \left(WW^T\right) P \right> = \left< Z, \partial^* \operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(XX^T\right) \partial^{*T} P \right>.
\end{equation*}
Thus we can conclude that $\operatorname{\mathcal{E}}_{\mu_{\mathbf{G}}}\! \left(WW^T\right) P = \partial^* \operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(XX^T\right) \partial^{*T} P$ for all $P \in \operatorname{ED}$ and hence that the two matrices are equal. This proves the first part. 

Multiplying this identity on the left by $\partial^{*+}$ and on the right by $\partial^{*T+}$, 
\begin{equation*}
\partial^{*+} \partial^* \operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(XX^T\right) \partial^{*T} \partial^{*T+} = \partial^{*+} \operatorname{\mathcal{E}}_{\mu_{\mathbf{G}}}\! \left(WW^T\right) \partial^{*T+}.
\end{equation*}
But $\partial^{*+} \partial^* = \operatorname{proj}_{\operatorname{im} \partial^{*+}} = \operatorname{proj}_{(\ker \partial^*)^\perp}$ is orthogonal projection onto the centered configurations. Since $\nu$ is already supported on the centered configurations, $\operatorname{im} \operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(XX^T\right) \subset (\ker \partial^*)^\perp$ and composing $\operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(XX^T\right)$ with this matrix has no effect. 

Similarly, $\partial^{*T} \partial^{*T+} = \operatorname{proj}_{\operatorname{im} \partial^{*T}} = \operatorname{proj}_{\operatorname{im} \partial^{*+}} = \operatorname{proj}_{(\ker \partial^*)^\perp}$ is the same projection. Again, $\ker \operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(XX^T\right) \supset \ker \partial^*$, so projecting to the orthogonal complement of this kernel before applying $\operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(XX^T\right)$ has no effect. This proves that $\operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(XX^T\right) = \partial^{*+} \operatorname{\mathcal{E}}_{\mu_{\mathbf{G}}}\! \left(WW^T\right) \partial^{*T+}$, as desired.

\label{thm:gyradius formula}\ifinner\else\mgp{\raggedright\tiny \ref{thm:gyradius formula} thm:gyradius formula}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{thm:gyradius formula} thm:gyradius formula}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{thm:gyradius formula} thm:gyradius formula}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{thm:gyradius formula} thm:gyradius formula}\ignorespaces\fi
If $\nu_{\mathbf{G}} = (\partial^{*+})_\sharp \mu_{\mathbf{G}}$ where $\mu_{\mathbf{G}}$ is any $O(d)$-invariant probability measure concentrated on $\operatorname{im} \partial^*$, then if $\Sigma_\mathbf{v}$ and $\Sigma_\mathbf{e}$ are as defined in~Proposition~\ref{prop:block structure of XXt} and~Proposition~\ref{prop:block structure of WWt}, we have
\begin{align*}
\left< \operatorname{R^2_g} \right>_{\nu_{\mathbf{G}}} = \frac{d}{\mathbf{v}} \operatorname{tr} (\Sigma_\mathbf{v})
	      = \frac{d}{\mathbf{v}} \operatorname{tr} (\partial^{T+} \Sigma_\mathbf{e} \partial^{+}).
\end{align*}

\label{cor:phantom network theory}\ifinner\else\mgp{\raggedright\tiny \ref{cor:phantom network theory} cor:phantom network theory}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{cor:phantom network theory} cor:phantom network theory}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{cor:phantom network theory} cor:phantom network theory}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{cor:phantom network theory} cor:phantom network theory}\ignorespaces\fi
In James--Guth phantom network theory $\mu$ is a standard Gaussian on $\operatorname{ED}$. For any graph $\mathbf{G}$, $\mu$ is admissible and compatible with $\mathbf{G}$ and $\mu_{\mathbf{G}} = \mu^0_{\mathbf{G}}$ is a standard Gaussian on $\operatorname{im} \partial^*$. Further, 
\begin{equation}
\left< \operatorname{R^2_g} \right>_{\nu_{\mathbf{G}}} =  \frac{d}{\mathbf{v}} \operatorname{tr} L^+.
\end{equation}

We showed in~Corollary~\ref{cor:phantom network theory works} that $\mu$ is admissible and compatible with $\mathbf{G}$, so $\mu_{\mathbf{G}}$ is well-defined. Further, by~Proposition~\ref{prop:disintegration}, $\mu_{\mathbf{G}}$ has $O(d)$-invariance and concentration on $\operatorname{im} \partial^*$ so~Theorem~\ref{thm:gyradius formula} applies. It is easy to see that $\operatorname{\mathcal{E}}_{\mu_{\mathbf{G}}}\! \left(WW^T\right)$ is orthogonal projection onto $\operatorname{im} \partial^*$. It follows from~Proposition~\ref{prop:block structure of WWt} that $\Sigma_\mathbf{e}$ is the orthogonal projection $\partial^T \partial^{T+}$ to $\operatorname{im} \partial^T$. Thus
\begin{equation*}
\left< \operatorname{R^2_g} \right>_{\nu_{\mathbf{G}}} = \frac{d}{\mathbf{v}} \operatorname{tr} \partial^{T+} (\partial^{T} \partial^{T+}) \partial^+ = \frac{d}{\mathbf{v}} \operatorname{tr} \partial^{T+} \partial^+ = \frac{d}{\mathbf{v}} \operatorname{tr} L^+,
\end{equation*}
as claimed.

\label{prop:cycle graph gyradius}\ifinner\else\mgp{\raggedright\tiny \ref{prop:cycle graph gyradius} prop:cycle graph gyradius}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{prop:cycle graph gyradius} prop:cycle graph gyradius}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{prop:cycle graph gyradius} prop:cycle graph gyradius}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{prop:cycle graph gyradius} prop:cycle graph gyradius}\ignorespaces\fi
Suppose that $\mathbf{G}$ is the $n$-edge cycle graph, $\mu$ is the joint distribution of $n$ i.i.d.\,random edges in $\mathbb{R}^d$ chosen from some $O(d)$-invariant probability measure on $\mathbb{R}^d$, and $\mu$ is compatible with $\mathbf{G}$. Then $\mu_{\mathbf{G}}$ is permutation invariant, all $\operatorname{\mathcal{E}}_{\mu_{\mathbf{G}}}\! \left(\left\| W(e_i) \right\|^2\right)$ are equal and if their common value is $\lambda$ then 
\begin{equation*}
\left< \operatorname{R^2_g} \right>_{\nu_{\mathbf{G}}} = \frac{\lambda (\mathbf{e} + 1)}{12}.
\end{equation*}

\label{cor:Gaussian ring}\ifinner\else\mgp{\raggedright\tiny \ref{cor:Gaussian ring} cor:Gaussian ring}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{cor:Gaussian ring} cor:Gaussian ring}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{cor:Gaussian ring} cor:Gaussian ring}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{cor:Gaussian ring} cor:Gaussian ring}\ignorespaces\fi
Let $\mathbf{G}$ be the $\mathbf{e}$-edge cycle graph and $\mu$ be the standard Gaussian on $\operatorname{ED} = (\mathbb{R}^3)^\mathbf{e}$. $\mu$ is admissible and compatible with $\mathbf{G}$, $\mu_{\mathbf{G}} = \mu^0_{\mathbf{G}}$ is well-defined, and 
\begin{equation*}
\left< \operatorname{R^2_g} \right>_{\nu_{\mathbf{G}}} = (\mathbf{e}^2 - 1)/(12 \mathbf{e})
\end{equation*}

\label{prop:chain map pushforwards}\ifinner\else\mgp{\raggedright\tiny \ref{prop:chain map pushforwards} prop:chain map pushforwards}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{prop:chain map pushforwards} prop:chain map pushforwards}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{prop:chain map pushforwards} prop:chain map pushforwards}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{prop:chain map pushforwards} prop:chain map pushforwards}\ignorespaces\fi
Suppose $f_0$ and $f_1$ are injective chain maps $\mathbf{G}' \rightarrow \mathbf{G}$, and $\mathbf{G}$ and $\mathbf{G}'$ have the same cycle rank $\mathbf{e} - \mathbf{v} + 1 = \mathbf{e}' - \mathbf{v}' + 1$. 
Then 
\begin{enumerate}
\item $\operatorname{proj}_{\operatorname{ID}'} f_1^*$ is an invertible linear map between $\operatorname{ID}$ and $\operatorname{ID}'$, \label{projidprime f1star is invertible}\ifinner\else\mgp{\raggedright\tiny \ref{projidprime f1star is invertible} projidprime f1star is invertible}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{projidprime f1star is invertible} projidprime f1star is invertible}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{projidprime f1star is invertible} projidprime f1star is invertible}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{projidprime f1star is invertible} projidprime f1star is invertible}\ignorespaces\fi
\item \label{mu and mup compatible with gprime}\ifinner\else\mgp{\raggedright\tiny \ref{mu and mup compatible with gprime} mu and mup compatible with gprime}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{mu and mup compatible with gprime} mu and mup compatible with gprime}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{mu and mup compatible with gprime} mu and mup compatible with gprime}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{mu and mup compatible with gprime} mu and mup compatible with gprime}\ignorespaces\fi $\mu$ is compatible with $\mathbf{G}$ $\implies$ $\mu' := (f_1^*)_\sharp \mu$ is compatible with $\mathbf{G}'$, 
\item \label{mugwp are pushmugw}\ifinner\else\mgp{\raggedright\tiny \ref{mugwp are pushmugw} mugwp are pushmugw}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{mugwp are pushmugw} mugwp are pushmugw}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{mugwp are pushmugw} mugwp are pushmugw}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{mugwp are pushmugw} mugwp are pushmugw}\ignorespaces\fi Since $\mu$ is compatible with $\mathbf{G}$, by definition there is an open ball $U \subset \operatorname{ID}$ centered at $0$ so that $\mu^W_{\mathbf{G}}$ is defined for all $W \in U$. If we let $W' := (\operatorname{proj}_{\operatorname{ID}'} f_1^*) W$ then for all $W'$ in an open ball $U'$ centered at $0$ in $\operatorname{ID}'$, there are corresponding $W \in U$ so that 
\begin{equation*}
(\mu')_{\mathbf{G}'}^{W'} = (f_1^*)_\sharp \mu^W_{\mathbf{G}}.
\end{equation*}
\end{enumerate}

We start by working out some properties of $f_1$ and $f_1^*$ which follow from our hypotheses.

\begin{claim}\label{claim:chain maps}\ifinner\else\mgp{\raggedright\tiny \ref{claim:chain maps} claim:chain maps}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{claim:chain maps} claim:chain maps}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{claim:chain maps} claim:chain maps}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{claim:chain maps} claim:chain maps}\ignorespaces\fi
We have $f_1 (\ker \partial') = \ker \partial$. Thus $\ker f_1^* \subset \operatorname{im} \partial^*$.
\end{claim}

\begin{proof}
If $w' \in \ker \partial'$, then $0 = f_0 \partial' w' = \partial f_1 w'$, so $f_1 w' \in \ker \partial$. Thus $f_1(\ker \partial') \subset \ker \partial$. Since $f_1$ is injective, $\dim f_1 (\ker \partial') = \dim \ker \partial'$. But $\dim \ker \partial' = \dim \ker \partial$ because each is the cycle rank $\mathbf{e} - \mathbf{v} + 1 = \mathbf{e}' - \mathbf{v}' + 1$. Thus $f_1(\ker \partial') = \ker \partial$.

Next, since $\ker \partial \subset \operatorname{im} f_1$, we know $(\operatorname{im} f_1)^0 \subset (\ker \partial)^0$. But $\ker f_1^* = (\operatorname{im} f_1)^0$ and $(\ker \partial)^0 = \operatorname{im} \partial^*$, so this proves $\ker f_1^* \subset \operatorname{im} \partial^*$.
\end{proof}

\begin{claim} \label{claim:images}\ifinner\else\mgp{\raggedright\tiny \ref{claim:images} claim:images}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{claim:images} claim:images}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{claim:images} claim:images}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{claim:images} claim:images}\ignorespaces\fi
We have $f_1^*(\operatorname{im} \partial^*) = \operatorname{im} (\partial')^*$ and $(f_1^*)^{-1}(\operatorname{im} (\partial')^*) = \operatorname{im} \partial^*$.
\end{claim}

\begin{proof}
Since $f_1(\ker \partial') = \ker \partial$, $f_1^* (\ker \partial)^0 = (\ker \partial')^0$, or $f_1^*(\operatorname{im} \partial^*) = \operatorname{im} (\partial')^*$. It follows immediately that $(f_1^*)^{-1}(\operatorname{im} (\partial')^*) = (f_1^*)^{-1}(f_1^*(\operatorname{im} \partial^*))$, so $\operatorname{im} \partial^* \subset (f_1^*)^{-1}(\operatorname{im} (\partial')^*)$. 

Now suppose $f_1^* W \in \operatorname{im} (\partial')^*$. Then $f_1^* W = (\partial')^* X' = (\partial')^* f_0^* X = f_1^* \partial^* X$ for some $X \in \operatorname{VP}$, where the second equality follows from surjectivity of $f_0^*$ (Corollary~\ref{cor:injective dual to surjective}). This means that $\partial^*X - W \in \ker f_1^*$. But $\ker f_1^* \subset \operatorname{im} \partial^*$ by the last claim, so $\partial^*X - W \in \operatorname{im} \partial^*$, and $W \in \operatorname{im} \partial^*$, as required.
\end{proof}

\begin{claim} \label{claim:id isomorphism}\ifinner\else\mgp{\raggedright\tiny \ref{claim:id isomorphism} claim:id isomorphism}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{claim:id isomorphism} claim:id isomorphism}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{claim:id isomorphism} claim:id isomorphism}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{claim:id isomorphism} claim:id isomorphism}\ignorespaces\fi
The map $\operatorname{proj}_{\operatorname{ID}'} f_1^*$ is a linear isomorphism from $\operatorname{ID}$ to $\operatorname{ID}'$. 
\end{claim}

\begin{proof}
First, it's clear that $\operatorname{im} \operatorname{proj}_{\operatorname{ID}'} f_1^* \subset \operatorname{ID}'$. Next, we show that $\operatorname{proj}_{\operatorname{ID}'} f_1^*$ restricted to $\operatorname{ID}$ has kernel $0$. Suppose that $W \in \operatorname{ID}$ has $\operatorname{proj}_{\operatorname{ID}'} f_1^* W = 0$. Then $f_1^* W \in \ker \operatorname{proj}_{\operatorname{ID}'} = \operatorname{im} (\partial')^*$. By~Claim~\ref{claim:images}, this implies $W \in \operatorname{im} \partial^*$. But $\operatorname{im} \partial^* \cap \operatorname{ID} = 0$, so this means $W = 0$. Thus $\operatorname{proj}_{\operatorname{ID}'} f_1^*$ restricted to $\operatorname{ID}$ is injective. But $\dim \operatorname{ID}' = d \xi(\mathbf{G}') = d \xi(\mathbf{G}) = \dim \operatorname{ID}$, which means that $\operatorname{proj}_{\operatorname{ID}'} f_1^*$ restricted to $\operatorname{ID}$ is an isomorphism.
\end{proof}

\begin{claim}\label{claim:proj f1 proj is proj f1}\ifinner\else\mgp{\raggedright\tiny \ref{claim:proj f1 proj is proj f1} claim:proj f1 proj is proj f1}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{claim:proj f1 proj is proj f1} claim:proj f1 proj is proj f1}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{claim:proj f1 proj is proj f1} claim:proj f1 proj is proj f1}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{claim:proj f1 proj is proj f1} claim:proj f1 proj is proj f1}\ignorespaces\fi
We claim that $\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}} = \operatorname{proj}_{\operatorname{ID}'} f_1^*$.
\end{claim}

\begin{proof}
Any $W \in \operatorname{ED}$ can be written uniquely as $W = \partial^* X + W_{\operatorname{ID}}$ for some $X \in \operatorname{VP}$ and $W_{\operatorname{ID}} \in \operatorname{ID}$. Now $f_1^* \partial^* X \in \operatorname{im} (\partial')^* = \ker \operatorname{proj}_{\operatorname{ID}'}$ by~Claim~\ref{claim:images}. Thus $\operatorname{proj}_{\operatorname{ID}'} f_1^* W = \operatorname{proj}_{\operatorname{ID}'} f_1^* W_{\operatorname{ID}}$. But $\operatorname{proj}_{\operatorname{ID}} W = W_{\operatorname{ID}}$, so 
$\operatorname{proj}_{\operatorname{ID}'} f_1^* W_{\operatorname{ID}} = \operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}} W$, as required.
\end{proof}

\begin{claim}\label{claim:fiber is pushforward of fiber}\ifinner\else\mgp{\raggedright\tiny \ref{claim:fiber is pushforward of fiber} claim:fiber is pushforward of fiber}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{claim:fiber is pushforward of fiber} claim:fiber is pushforward of fiber}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{claim:fiber is pushforward of fiber} claim:fiber is pushforward of fiber}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{claim:fiber is pushforward of fiber} claim:fiber is pushforward of fiber}\ignorespaces\fi
Recalling that $W' = \operatorname{proj}_{\operatorname{ID}'} f_1^* W$, we claim that $\operatorname{proj}_{\operatorname{ID}'}^{-1}(W') = f_1^* \operatorname{proj}_{\operatorname{ID}}^{-1}(W)$.
\end{claim}

\begin{proof}[Proof of claim]
We first show that $f_1^* \operatorname{proj}_{\operatorname{ID}}^{-1}(W) \subset \operatorname{proj}_{\operatorname{ID}'}^{-1}(W')$. Suppose $Z \in \operatorname{proj}_{\operatorname{ID}}^{-1}(W)$. Then $\operatorname{proj}_{\operatorname{ID}} Z = W$, so $\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}} Z = \operatorname{proj}_{\operatorname{ID}'} f_1^* W = W'$. But by~Claim~\ref{claim:proj f1 proj is proj f1}, $\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}} Z = \operatorname{proj}_{\operatorname{ID}'} f_1^* Z$. Therefore, $f_1^* Z \in \operatorname{proj}_{\operatorname{ID}'}^{-1}(W')$, as required.

Now we show that $\operatorname{proj}_{\operatorname{ID}'}^{-1}(W') \subset f_1^* \operatorname{proj}_{\operatorname{ID}}^{-1}(W)$. Suppose that we have $Z' \in \operatorname{proj}_{\operatorname{ID}'}^{-1}(W')$. Then $\operatorname{proj}_{\operatorname{ID}'} Z' = W'$. Now $f_1^*$ is surjective, so there exists some $Z \in \operatorname{ED}$ with $f_1^* Z = Z'$. We now know that $\operatorname{proj}_{\operatorname{ID}'} f_1^* Z = W'$. We must show that $Z \in \operatorname{proj}_{\operatorname{ID}}^{-1}(W)$. By~Claim~\ref{claim:proj f1 proj is proj f1}, we know 
\begin{equation*}
\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}} Z = \operatorname{proj}_{\operatorname{ID}'} f_1^* Z = W' = \operatorname{proj}_{\operatorname{ID}'} f_1^* W.
\end{equation*}
But by~Claim~\ref{claim:id isomorphism}, since $\operatorname{proj}_{\operatorname{ID}} Z \in \operatorname{ID}$ and $W \in \operatorname{ID}$, this implies that $\operatorname{proj}_{\operatorname{ID}} Z = W$, as required.
\end{proof}

\begin{claim}
$(f_1^*)_\sharp \mu$ is an admissible measure on $\operatorname{ED}$.
\end{claim}

\begin{proof}
Since $f_1^*$ is a linear map, it is Lipschitz. Further, Lipschitz pushforwards of Radon probability measures with finite first moment are also Radon probability measures of finite first moment~\cite{Fritz2019}, so $(f_1^*)_\sharp \mu$ is admissible.
\end{proof}

We are now ready for the body of the proof. We noted in~Definition~\ref{def:tjur conditional probability} that Tjur conditional probabilities are unique if they are defined. Therefore, we can establish both~\ref{mu and mup compatible with gprime} and~\ref{mugwp are pushmugw} by showing that the $(f_1^*)_\sharp \mu^W_{\mathbf{G}}$ are conditional probabilities for $\mu'$ given $\operatorname{proj}_{\operatorname{ID}'} Z' = W'$.

\begin{claim}
The $\mu^W_{\mathbf{G}}$ are conditional probabilities for $\mu$ given $\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}}(Z) = W'$.
\end{claim}

\begin{proof}[Proof of claim]
By~Claim~\ref{claim:proj f1 proj is proj f1}, we know that $\mu'_{\operatorname{ID}'} = (\operatorname{proj}_{\operatorname{ID}'})_\sharp \mu' = (\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}})_\sharp \mu$.

So suppose we fix some $f \in \mathcal{K}(\operatorname{ED})$ and some $\epsilon > 0$. By hypothesis, there is some open neighborhood $V$ of $W$ in $\operatorname{ID}$ so that for every $B \subset V$ with $\mu_{\operatorname{ID}}(B) > 0$ we have $\lvert\mu^W_{\mathbf{G}}(f) - \mu^B(f)\rvert < \epsilon$. Now the map $\operatorname{proj}_{\operatorname{ID}'} f_1^*$ is a linear isomorphism from $\operatorname{ID}$ to $\operatorname{ID}'$ by~Claim~\ref{claim:id isomorphism}. Therefore, there is some open neighborhood $V'$ of $W' = \operatorname{proj}_{\operatorname{ID}'} f_1^* W$ so that $(\operatorname{proj}_{\operatorname{ID}'} f_1^*)^{-1}(V') \subset V$. Now suppose we have any $B' \subset V'$ with $\mu'_{\operatorname{ID}'}(B') > 0$. Defining $B$ to be the inverse image $B := (\operatorname{proj}_{\operatorname{ID}'} f_1^*)^{-1}(B')$, and applying the definition of pushforward, we now know that
\begin{equation*}
0 < \mu'_{\operatorname{ID}'}(B') = (\operatorname{proj}_{\operatorname{ID}})_\sharp \mu( (\operatorname{proj}_{\operatorname{ID}'} f_1^*)^{-1}(B') ) = \mu_{\operatorname{ID}}(B).
\end{equation*}
Further, since $B' \subset V'$, we know $B \subset V$. We now compute
\begin{align*}
(\mu')^{B'}(f) &= \frac{1}{\mu'_{\operatorname{ID}'}(B')} \int_{(\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}})^{-1}(B')} f(Z) \mu(dZ) \\
&= \frac{1}{\mu_{\operatorname{ID}}(B)} \int_{(\operatorname{proj}_{\operatorname{ID}})^{-1}(B)} f(Z) \mu(dZ) = \mu^B(f)
\end{align*}
This proves that $\lvert\mu^W_{\mathbf{G}}(f) - (\mu')^{B'}(f)\rvert = \lvert\mu^W_{\mathbf{G}}(f) - \mu^B(f)\rvert < \epsilon$, and hence that the $\mu^W_{\mathbf{G}}$ are conditional probabilities for $\mu$ given $\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}}(W) = W'$.
\end{proof}

Applying~Theorem~\ref{thm:decomposition and existence}, we now know that the $\mu^W_{\mathbf{G}}$ and $\mu'_{\operatorname{ID}'}$ are a decomposition of $\mu$ with respect to the map $\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}} = \operatorname{proj}_{\operatorname{ID}'} f_1^*$.
By~Lemma~\ref{lem:decompositions push forward}, the $(f_1^*)_\sharp \mu^W_{\mathbf{G}}$ and $\mu'_{\operatorname{ID}'}$ are thus a decomposition of $f_1^* \mu = \mu'$ with respect to $\operatorname{proj}_{\operatorname{ID}'}$. One last application of~Theorem~\ref{thm:decomposition and existence} shows that the $(f_1^*)_\sharp \mu^W_{\mathbf{G}}$ are conditional probabilities for $\mu'$ given $\operatorname{proj}_{\operatorname{ID}'} (Z') = W'$, as desired.

We first show that $f_1^* \operatorname{proj}_{\operatorname{ID}}^{-1}(W) \subset \operatorname{proj}_{\operatorname{ID}'}^{-1}(W')$. Suppose $Z \in \operatorname{proj}_{\operatorname{ID}}^{-1}(W)$. Then $\operatorname{proj}_{\operatorname{ID}} Z = W$, so $\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}} Z = \operatorname{proj}_{\operatorname{ID}'} f_1^* W = W'$. But by~Claim~\ref{claim:proj f1 proj is proj f1}, $\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}} Z = \operatorname{proj}_{\operatorname{ID}'} f_1^* Z$. Therefore, $f_1^* Z \in \operatorname{proj}_{\operatorname{ID}'}^{-1}(W')$, as required.

Now we show that $\operatorname{proj}_{\operatorname{ID}'}^{-1}(W') \subset f_1^* \operatorname{proj}_{\operatorname{ID}}^{-1}(W)$. Suppose that we have $Z' \in \operatorname{proj}_{\operatorname{ID}'}^{-1}(W')$. Then $\operatorname{proj}_{\operatorname{ID}'} Z' = W'$. Now $f_1^*$ is surjective, so there exists some $Z \in \operatorname{ED}$ with $f_1^* Z = Z'$. We now know that $\operatorname{proj}_{\operatorname{ID}'} f_1^* Z = W'$. We must show that $Z \in \operatorname{proj}_{\operatorname{ID}}^{-1}(W)$. By~Claim~\ref{claim:proj f1 proj is proj f1}, we know 
\begin{equation*}
\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}} Z = \operatorname{proj}_{\operatorname{ID}'} f_1^* Z = W' = \operatorname{proj}_{\operatorname{ID}'} f_1^* W.
\end{equation*}
But by~Claim~\ref{claim:id isomorphism}, since $\operatorname{proj}_{\operatorname{ID}} Z \in \operatorname{ID}$ and $W \in \operatorname{ID}$, this implies that $\operatorname{proj}_{\operatorname{ID}} Z = W$, as required.

By~Claim~\ref{claim:proj f1 proj is proj f1}, we know that $\mu'_{\operatorname{ID}'} = (\operatorname{proj}_{\operatorname{ID}'})_\sharp \mu' = (\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}})_\sharp \mu$.

So suppose we fix some $f \in \mathcal{K}(\operatorname{ED})$ and some $\epsilon > 0$. By hypothesis, there is some open neighborhood $V$ of $W$ in $\operatorname{ID}$ so that for every $B \subset V$ with $\mu_{\operatorname{ID}}(B) > 0$ we have $\lvert\mu^W_{\mathbf{G}}(f) - \mu^B(f)\rvert < \epsilon$. Now the map $\operatorname{proj}_{\operatorname{ID}'} f_1^*$ is a linear isomorphism from $\operatorname{ID}$ to $\operatorname{ID}'$ by~Claim~\ref{claim:id isomorphism}. Therefore, there is some open neighborhood $V'$ of $W' = \operatorname{proj}_{\operatorname{ID}'} f_1^* W$ so that $(\operatorname{proj}_{\operatorname{ID}'} f_1^*)^{-1}(V') \subset V$. Now suppose we have any $B' \subset V'$ with $\mu'_{\operatorname{ID}'}(B') > 0$. Defining $B$ to be the inverse image $B := (\operatorname{proj}_{\operatorname{ID}'} f_1^*)^{-1}(B')$, and applying the definition of pushforward, we now know that
\begin{equation*}
0 < \mu'_{\operatorname{ID}'}(B') = (\operatorname{proj}_{\operatorname{ID}})_\sharp \mu( (\operatorname{proj}_{\operatorname{ID}'} f_1^*)^{-1}(B') ) = \mu_{\operatorname{ID}}(B).
\end{equation*}
Further, since $B' \subset V'$, we know $B \subset V$. We now compute
\begin{align*}
(\mu')^{B'}(f) &= \frac{1}{\mu'_{\operatorname{ID}'}(B')} \int_{(\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}})^{-1}(B')} f(Z) \mu(dZ) \\
&= \frac{1}{\mu_{\operatorname{ID}}(B)} \int_{(\operatorname{proj}_{\operatorname{ID}})^{-1}(B)} f(Z) \mu(dZ) = \mu^B(f)
\end{align*}
This proves that $\lvert\mu^W_{\mathbf{G}}(f) - (\mu')^{B'}(f)\rvert = \lvert\mu^W_{\mathbf{G}}(f) - \mu^B(f)\rvert < \epsilon$, and hence that the $\mu^W_{\mathbf{G}}$ are conditional probabilities for $\mu$ given $\operatorname{proj}_{\operatorname{ID}'} f_1^* \operatorname{proj}_{\operatorname{ID}}(W) = W'$.

We are first going to do a bit of linear algebra.
\begin{claim} \label{claim:f0star and ker bdystar}\ifinner\else\mgp{\raggedright\tiny \ref{claim:f0star and ker bdystar} claim:f0star and ker bdystar}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{claim:f0star and ker bdystar} claim:f0star and ker bdystar}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{claim:f0star and ker bdystar} claim:f0star and ker bdystar}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{claim:f0star and ker bdystar} claim:f0star and ker bdystar}\ignorespaces\fi
$f_0^*(\ker \partial^*) = \ker (\partial')^*$.
\end{claim}

\begin{proof}[Proof of claim] 
We know that $\partial f_1 = f_0 \partial'$ since $f_0$ and $f_1$ are chain maps. Thus if $x \in \operatorname{im} \partial'$, then $f_0 x = f_0 \partial' w = \partial f_1 w$, so $f_0 x \in \operatorname{im} \partial$. Thus $f_0( \operatorname{im} \partial' ) \subset \operatorname{im} \partial$. But this means that $(\operatorname{im} \partial')^0 \subset f_0^* (\operatorname{im} \partial)^0$, or $\ker (\partial')^* \subset f_0^*(\ker \partial^*)$. However, from~Proposition~\ref{prop:ker and im of bdystar}, we know that $\dim \ker (\partial')^* = \dim \ker \partial^* = d$. Since $\dim f_0^*(\ker \partial^*) \leq \dim \ker \partial^* = d$, we have shown that $\ker (\partial')^* = f_0^*(\ker \partial^*)$. 
\end{proof}

\begin{claim}
The map $g'$ is $O(d)$ and translation invariant.
\end{claim}

\begin{proof}[Proof of claim]
By definition, $g(X) = g'(f_0^*(X))$. To show that $g'$ is translation-invariant, we observe that the translations given by $\ker (\partial')^*$. So if $Y'$ is a translation, $Y' = f_0^* Y$ (by the last~Claim~\ref{claim:f0star and ker bdystar}). Further, $f_0^*$ is surjective, so for any $X' \in \operatorname{VP}'$, there is some $X \in \operatorname{VP}$ so that $X' = f_0^* X$. Now suppose $X \in \operatorname{VP}$ and $Y \in \ker (\partial')^*$: 
\begin{equation*}
g'(X' + Y') = g'(f_0^*(X) + f_0^*(Y)) = g'(f_0^*(X + Y)) = g(X + Y) = g(X) = g'(f_0(X)) = g'(X').
\end{equation*}
where the step $g(X+Y) = g(X)$ follows from $Y \in \ker \partial^*$ and the translation-invariance of $g$. 

By Lemma~\ref{lem:linear equivariance}, $f_0^* = I_d \otimes f_0^T$ is $GL(d)$-equivariant, and hence in particular $O(d)$-equivariant. To see what this means precisely, suppose that $Q \in O(d)$, so that the action of $Q$ on $\operatorname{VP}$ is $Q \otimes I_{\mathbf{v}}$ and the action of $Q$ on $\operatorname{VP}'$ is $Q \otimes I_{\mathbf{v}'}$. Since $f_0^T$ is a $\mathbf{v}' \times \mathbf{v}$ matrix: 
\begin{equation*}
(Q \otimes I_{\mathbf{v}'}) f_0^* = (Q \otimes I_{\mathbf{v}'})(I_d \otimes f_0^T) 
= (Q \otimes f_0^T) = (I_d \otimes f_0^T)(Q \otimes I_{\mathbf{v}}) = f_0^* (Q \otimes I_{\mathbf{v}}).
\end{equation*}
where we used Lemma~\ref{lem:mixed product} in the middle steps. We then have
\begin{equation*}
g'( (Q \otimes I_{\mathbf{v}'}) X' ) = g'( (Q \otimes I_{\mathbf{v}'}) f_0^* X ) =
g' (f_0^* (Q \otimes I_{\mathbf{v}} X)) = g((Q \otimes I_{\mathbf{v}}) X) =
g(X) = g'(f_0^* X) = g'(X').
\end{equation*}
which completes the proof.
\end{proof}
We know from~Proposition~\ref{prop:expectations under pushforwards} that $\operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(g\right) = \operatorname{\mathcal{E}}_{(f_0^*)_\sharp \nu_{\mathbf{G}}}\! \left(g'\right)$. So we must show that $\operatorname{\mathcal{E}}_{(f_0^*)_\sharp \nu_{\mathbf{G}}}\! \left(g'\right) = \operatorname{\mathcal{E}}_{\nu'_{\mathbf{G}'}}\! \left(g'\right)$. Now we have just proved that $g'$ is translation-invariant, so the expectation of $g'$ with respect to $(f_0^*)_\sharp \nu_{\mathbf{G}}$ is equal to the expectation of $g'$ with respect to $(\operatorname{proj}_{\operatorname{im} (\partial')^{*+}})_\sharp (f_0^*)_\sharp \nu_{\mathbf{G}}$. It now suffices to show that $(\operatorname{proj}_{\operatorname{im} (\partial')^{*+}} f_0^*)_\sharp \nu_{\mathbf{G}} = \nu'_{\mathbf{G}'}$.

After all our work above, this is mostly a matter of unpacking definitions. Recall that $\nu_{\mathbf{G}} := \partial^{*+}_\sharp \mu_{\mathbf{G}}$ and $\nu'_{\mathbf{G}'} := (\partial')^{*+}_\sharp (\mu')_{\mathbf{G}'}$. In the proof of~Proposition~\ref{prop:chain map pushforwards}, we showed $(\mu')_{\mathbf{G}'} = (f_1^*)_\sharp \mu_{\mathbf{G}}$. Now we can just compute:
\begin{align*}
(\operatorname{proj}_{\operatorname{im} (\partial')^{*+}} f_0^*)_\sharp \nu_{\mathbf{G}} &= 
(\operatorname{proj}_{\operatorname{im} (\partial')^{*+}} f_0^* \partial^{*+})_\sharp \mu_{\mathbf{G}} 
= ((\partial')^{*+} (\partial')^* f_0^* \partial^{*+})_\sharp \mu_{\mathbf{G}} \\
&= ((\partial')^{*+} f_1^* \partial^* \partial^{*+})_\sharp \mu_{\mathbf{G}} 
= ((\partial')^{*+} f_1^*)_\sharp (\operatorname{proj}_{\operatorname{im} \partial^*})_\sharp \mu_{\mathbf{G}} \\
&= ((\partial')^{*+} f_1^*)_\sharp \mu_{\mathbf{G}} = (\partial')^{*+}_\sharp (f_1^*)_\sharp \mu_{\mathbf{G}} \\
&= (\partial')^{*+}_\sharp (\mu')_{\mathbf{G}'} = \nu'_{\mathbf{G}'},
\end{align*}
where $(\operatorname{proj}_{\operatorname{im} \partial^*})_\sharp \mu_{\mathbf{G}} = \mu_{\mathbf{G}}$ because $\mu_{\mathbf{G}}$ is concentrated on $\operatorname{im} \partial^*$ by construction.

By definition, $g(X) = g'(f_0^*(X))$. To show that $g'$ is translation-invariant, we observe that the translations given by $\ker (\partial')^*$. So if $Y'$ is a translation, $Y' = f_0^* Y$ (by the last~Claim~\ref{claim:f0star and ker bdystar}). Further, $f_0^*$ is surjective, so for any $X' \in \operatorname{VP}'$, there is some $X \in \operatorname{VP}$ so that $X' = f_0^* X$. Now suppose $X \in \operatorname{VP}$ and $Y \in \ker (\partial')^*$: 
\begin{equation*}
g'(X' + Y') = g'(f_0^*(X) + f_0^*(Y)) = g'(f_0^*(X + Y)) = g(X + Y) = g(X) = g'(f_0(X)) = g'(X').
\end{equation*}
where the step $g(X+Y) = g(X)$ follows from $Y \in \ker \partial^*$ and the translation-invariance of $g$. 

By Lemma~\ref{lem:linear equivariance}, $f_0^* = I_d \otimes f_0^T$ is $GL(d)$-equivariant, and hence in particular $O(d)$-equivariant. To see what this means precisely, suppose that $Q \in O(d)$, so that the action of $Q$ on $\operatorname{VP}$ is $Q \otimes I_{\mathbf{v}}$ and the action of $Q$ on $\operatorname{VP}'$ is $Q \otimes I_{\mathbf{v}'}$. Since $f_0^T$ is a $\mathbf{v}' \times \mathbf{v}$ matrix: 
\begin{equation*}
(Q \otimes I_{\mathbf{v}'}) f_0^* = (Q \otimes I_{\mathbf{v}'})(I_d \otimes f_0^T) 
= (Q \otimes f_0^T) = (I_d \otimes f_0^T)(Q \otimes I_{\mathbf{v}}) = f_0^* (Q \otimes I_{\mathbf{v}}).
\end{equation*}
where we used Lemma~\ref{lem:mixed product} in the middle steps. We then have
\begin{equation*}
g'( (Q \otimes I_{\mathbf{v}'}) X' ) = g'( (Q \otimes I_{\mathbf{v}'}) f_0^* X ) =
g' (f_0^* (Q \otimes I_{\mathbf{v}} X)) = g((Q \otimes I_{\mathbf{v}}) X) =
g(X) = g'(f_0^* X) = g'(X').
\end{equation*}
which completes the proof.

\label{prop:subdivisions and expectations}\ifinner\else\mgp{\raggedright\tiny \ref{prop:subdivisions and expectations} prop:subdivisions and expectations}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{prop:subdivisions and expectations} prop:subdivisions and expectations}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{prop:subdivisions and expectations} prop:subdivisions and expectations}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{prop:subdivisions and expectations} prop:subdivisions and expectations}\ignorespaces\fi
If $\mathbf{G}_n$ is the $n$-part edge subdivision of $\mathbf{G}$, and we have a measure $\mu_n$ on $\operatorname{ED}_n$ which is compatible with $\mathbf{G}_n$, then $\mu := (f_1^*)_\sharp \mu_n$ is compatible with $\mathbf{G}$ and for any $O(d)$ and translation-invariant measurable function $g_n$ on $\operatorname{VP}_n$ which can be expressed in terms of $\mathbf{G}$ as $g_n = g \circ (f_0)^*$ then
\begin{equation*}
\operatorname{\mathcal{E}}_{\nu_{\mathbf{G}_n}}\! \left(g_n\right) = \operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(g\right)
\end{equation*}

\label{prop:projections}\ifinner\else\mgp{\raggedright\tiny \ref{prop:projections} prop:projections}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{prop:projections} prop:projections}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{prop:projections} prop:projections}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{prop:projections} prop:projections}\ignorespaces\fi
Suppose $\mathbf{G}$ is a connected graph with cycle rank $r$. Take any orthonormal basis $\ell_1, \dots, \ell_r$ for the loop space $\ker \partial \subset \operatorname{EC}$ and any $p \in \operatorname{EC}$ with $\partial p = v_i - v_j$. In phantom network theory (that is, when the probability measure $\mu$ on $\operatorname{ED}$ is a standard Gaussian) for embeddings of $\mathbf{G}$ in $\mathbb{R}^d$, 
\begin{equation*}
\operatorname{\mathcal{E}}_{\nu_\mathbf{G}}\! \left(\left\| X(v_i) - X(v_j) \right\|^2\right) = d \left(\left< p, p \right> - \sum\limits_{i=1}^r \left< p, \ell_i \right>^2 \right).
\end{equation*}

Let $\mathbf{G}'$ be the graph with two vertices $v'_1$ and $v'_2$, $r$ loop edges $e'_1, \dots, e'_r$ joining $v_1 \rightarrow v_1$, and a single edge $e'_{r+1}$ joining $v'_1 \rightarrow v'_2$.

Now define chain maps $f_0$ and $f_1$ by $f_0(v'_1) = v_j$ and $f_0(v'_2) = v_i$, while $f_1(e'_i) = \ell_i$ and $f_1(e'_{r+1}) = p$. It is easy to verify that $f_0 \partial' = \partial f_1$, as $\partial f_1 (e'_i) = \partial \ell_i = 0$ and $\partial f_1(e'_{r+1}) = v_i - v_j = f_0 \partial'(e'_{r+1})$. An example of this construction is shown in~Figure~\ref{fig:flower} where $\mathbf{G}$ is a subdivision of the $\alpha$-graph (which has cycle rank $3$). 

Since $\mu$ has covariance matrix $I_d \otimes I_\mathbf{e}$ on $\operatorname{ED}$, the pushforward $(f_1^*)_\sharp \mu$ has covariance matrix
\begin{equation*}
(f_1^*) (f_1^*)^T = (I_d \otimes f_1^T)(I_d \otimes f_1) = (I_d \otimes f_1^T f_1)
\end{equation*}
It follows from our definition of $f_1$ that $f_1^T f_1$ is a $2 \times 2$ block matrix with
\begin{equation*}
(f_1^T f_1)_{11} = I_{r}, \quad
(f_1^T f_1)_{12} = ( \left< \ell_1, p \right> \cdots \left< \ell_r, p \right> ), \quad
(f_1^T f_1)_{21} = (f_1^T f_1)_{12}^T, \quad
(f_1^T f_1)_{22} = \left< p, p \right>. 
\end{equation*}
The $d \times d$ covariance matrix of $((f_1^*)_\sharp \mu)_\mathbf{G}$ is the conditional variance of $W(e_{r+1})$ conditioned on $W(e_1), \dotsc, W(e_r) = 0$.

So far, everything we have said is true for an arbitrary $\mu$ on $\operatorname{ED}$ with covariance matrix $I_{d\mathbf{e}}$.  For an arbitrary $\mu$, we would need more information to continue, because the covariance matrix does not determine the conditional variance in general.

However, since we also know that $(f_1^*)_\sharp \mu$ is a Gaussian distribution in this special case, the conditional covariance matrix, which is the covariance matrix of $((f_1^*)_\sharp \mu)_\mathbf{G}$, can be computed by taking the Schur complement of $(f_1^T f_1)_{22}$ inside $f_1^T f_1$:
\begin{align*}
\operatorname{cov}_{((f_1^*)_\sharp \mu)_\mathbf{G}}\left( -, - \right) &= I_d \otimes ((f_1^T f_1)_{22} - (f_1^T f_1)_{12} (f_1^T f_1)_{11}^{-1} (f_1^T f_1)_{21}) \\
&= I_d \otimes (\left< p, p \right> - \sum \left< \ell_i, p \right>^2) = (\left< p, p \right> - \sum \left< \ell_i, p \right>^2) I_d.
\end{align*}
Now the expectation of $\left\| W(v_i) - W(v_j) \right\| = \left\| W'(v_2) - W'(v_1) \right\|$ is given by 
\begin{equation*}
\operatorname{cov}_{((f_1^*)_\sharp \mu)_\mathbf{G}}\left( \mathbf{1}_{d \times 1}, \mathbf{1}_{d \times 1} \right) = d(\left< p, p \right> - \sum \left< \ell_i, p \right>^2),
\end{equation*}
as claimed.

We are going to construct the conditional probabilities $(\mu_n)_{\mathbf{G}_n}^{W_n}$ by constructing a decomposition of $\mu_n$ with respect to $\operatorname{proj}_{\operatorname{ID}_n}$ and the measure $(\operatorname{proj}_{\operatorname{ID}_n})_\sharp \mu_n$, keeping in mind that $W_n$ is a member of $\operatorname{ED}_n = ((\mathbb{R}^d)^n)^\mathbf{e}$. We do this in several stages. We know that we have maps 
\begin{equation*}
\operatorname{ED}_n \xrightarrow{f_1^*} \operatorname{ED} \xrightarrow{\operatorname{proj}_{\operatorname{ID}}} \operatorname{ID} 
\end{equation*}
We first note that $\mu_n$ is the joint distribution of independent vectors in $(\mathbb{R}^d)^n$ chosen from the distributions $\rho_1, \dots, \rho_e$. Now as a $d \times dn$ matrix, $\operatorname{ftc} = I_d \otimes \mathbf{1}_{1 \times n}$. Further, we can compute
\begin{equation} \label{eq:kronecker subdivision}\ifinner\else\mgp{\raggedright\tiny \ref{eq:kronecker subdivision} eq:kronecker subdivision}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{eq:kronecker subdivision} eq:kronecker subdivision}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{eq:kronecker subdivision} eq:kronecker subdivision}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{eq:kronecker subdivision} eq:kronecker subdivision}\ignorespaces\fi
f_1^* = I_d \otimes f_1^T = I_d \otimes I_e \otimes \mathbf{1}_{1 \times n} = I_e \otimes I_d \otimes \mathbf{1}_{1 \times n} = I_e \otimes \operatorname{ftc}.
\end{equation}
Therefore, the pushforward $\mu = (f_1^*) \mu_n$ is the joint distribution of $\operatorname{ftc}_\sharp \rho_1, \dots, \operatorname{ftc}_\sharp \rho_\mathbf{e}$ on $\operatorname{ED} = (\mathbb{R}^d)^n$. We have assumed that the $\rho_i$ have decompositions with respect to $\operatorname{ftc}$, so we may construct a family of $(\mu_n)^Z$ decomposing $\mu_n$ with respect to $f_1^*$ by defining $(\mu_n)^Z$ as the joint distribution of the decomposing distributions $\rho_1^{Z(e_1)}, \dots, \rho_{\mathbf{e}}^{Z(e_\mathbf{e})}$. Further, we have assumed that $\mu$ is compatible with $\mathbf{G}$, so there are $\mu^W_{\mathbf{G}}$ decomposing $\mu$ with respect to $\operatorname{proj}_{\operatorname{ID}}$. 

Suppose we have some $g_n \in \mathcal{K}(\operatorname{ED}_n)$. We can define a new function $g$ by taking $g(Z) = (\mu_n)^Z(g_n)$. Since the $\mu_n^Z$ are weak$^*$-continuous in $Z$ as measures on $\operatorname{ED}$, their values on the fixed function $g_n$ are also a continuous function of $Z$. Further, since $g_n$ has compact support on $\operatorname{ED}_n$, the new function $g$ has compact support on $\operatorname{ED}$, and $g \in \mathcal{K}(\operatorname{ED})$.

We can then define a measure $(\mu_n)^W$ on $\operatorname{ED}_n$ by $(\mu_n)^W(g_n) = \mu^W_{\mathbf{G}}(g)$ for each $W$ in $U$ where $\mu^W_{\mathbf{G}}$ is defined. We claim that these $(\mu_n)^W$ and the measure $(\operatorname{proj}_{\operatorname{ID}} \circ f_1^*)_\# \mu_n$ are a decomposition of $\mu_n$ with respect to $\operatorname{proj}_{\operatorname{ID}} \circ f_1^*$  

Continuity of $(\mu_n)^W$ in $W$ follows from continuity of $\mu^W_{\mathbf{G}}$ in $W$. To show that $(\mu_n)^{W}$ is concentrated on $(\operatorname{proj}_{\operatorname{ID}} f_1^*)^{-1}(W)$, we argue as follows. Suppose $A$ is an open set in $\operatorname{ED}_n$ which is disjoint from $(\operatorname{proj}_{\operatorname{ID}} f_1^*)^{-1}(W)$ and $\chi_A(Z_n)$ is its characteristic function. The corresponding function $g(W) = (\mu_n)^W(\chi_A)$ is supported on $(f_1^*)(A)$, but by hypothesis, $f_1^*(A)$ is disjoint from $\operatorname{proj}_{\operatorname{ID}}^{-1}(W)$. Since $\mu^W_{\mathbf{G}}$ is concentrated on $\operatorname{proj}_{\operatorname{ID}}^{-1} W$, this means that $\mu^W_{\mathbf{G}}(g) = 0$. 

We last have to check the averaging property. This is a computation:
\begin{equation*}
\int (\mu_n)^W(g_n) (\operatorname{proj}_{\operatorname{ID}} \circ f_1^*)_\# \mu_n(dW)
= \int \mu^W_{\mathbf{G}}(g) (\operatorname{proj}_{\operatorname{ID}})_\sharp \mu(dW)
= \mu(g)
= (f_1^*)_\# \mu_n(g)
= \mu_n(g_n).
\end{equation*} 

Now it is clear from the definition of the canonical chain maps that they have no kernel. Therefore they are injective. One can give a sophisticated proof that $\xi(\mathbf{G}) = \xi(\mathbf{G}_n)$ because the two spaces are homotopy equivalent and $\xi$ is the first Betti number. However, it is easier to compute 
\begin{equation*}
\xi(\mathbf{G}) = \mathbf{e} - \mathbf{v} + 1 = n \mathbf{e} - (\mathbf{v} + (n-1) \mathbf{e}) + 1 = \xi(\mathbf{G}_n).
\end{equation*}
Therefore the hypotheses of~Proposition~\ref{prop:chain map pushforwards} hold. We've already proved in~Claim~\ref{claim:id isomorphism} of the proof of that Proposition that $\operatorname{proj}_{\operatorname{ID}} f_1^*$ is a linear isomorphism from $\operatorname{ID}_n$ to $\operatorname{ID}$. Therefore, there is an inverse map $(\operatorname{proj}_{\operatorname{ID}} f_1^*)^{-1} \colon \operatorname{ID} \rightarrow \operatorname{ID}_n$. Further, we saw in~Claim~\ref{claim:proj f1 proj is proj f1} that $\operatorname{proj}_{\operatorname{ID}} f_1^* = \operatorname{proj}_{\operatorname{ID}} f_1^* \operatorname{proj}_{\operatorname{ID}_n}$. Pushing our measure $(\operatorname{proj}_{\operatorname{ID}} f_1^*)_\# \mu_n$ on $\operatorname{ID}$ forward by $(\operatorname{proj}_{\operatorname{ID}} f_1^*)^{-1}$ to $\operatorname{ID}_n$, we see that
\begin{equation*}
(\operatorname{proj}_{\operatorname{ID}} f_1^*)^{-1}_\sharp (\operatorname{proj}_{\operatorname{ID}} f_1^*)_\sharp \mu_n = 
(\operatorname{proj}_{\operatorname{ID}} f_1^*)^{-1}_\sharp (\operatorname{proj}_{\operatorname{ID}} f_1^* \operatorname{proj}_{\operatorname{ID}_n})_\sharp \mu_n =
(\operatorname{proj}_{\operatorname{ID}_n})_\sharp \mu_n.
\end{equation*}
Thus we can define measures $(\mu_n)_{\mathbf{G}_n}^{W_n} := (\mu_n)^{(\operatorname{proj}_{\operatorname{ID}} f_1^*)^{-1}(W_n)}$ which decompose $\mu_n$ with respect to the map $\operatorname{proj}_{\operatorname{ID}_n}$ and the measure $(\operatorname{proj}_{\operatorname{ID}_n})_\sharp \mu_n$. By~Theorem~\ref{thm:decomposition and existence}, this shows that $\mu_n$ is compatible with $\mathbf{G}_n$.

\label{prop:freely jointed network}\ifinner\else\mgp{\raggedright\tiny \ref{prop:freely jointed network} prop:freely jointed network}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{prop:freely jointed network} prop:freely jointed network}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{prop:freely jointed network} prop:freely jointed network}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{prop:freely jointed network} prop:freely jointed network}\ignorespaces\fi
The measure $\mu_n$ in the freely jointed network $\mathbf{G}_n$ is compatible with $\mathbf{G}_n$. The corresponding measure $\mu$ on the structure graph $\mathbf{G}$ independently samples edge displacements from  
\begin{equation} \label{eq:freely jointed end-to-end}\ifinner\else\mgp{\raggedright\tiny \ref{eq:freely jointed end-to-end} eq:freely jointed end-to-end}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{eq:freely jointed end-to-end} eq:freely jointed end-to-end}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{eq:freely jointed end-to-end} eq:freely jointed end-to-end}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{eq:freely jointed end-to-end} eq:freely jointed end-to-end}\ignorespaces\fi
\rho(x) = \left(\frac{1}{2\pi^2 \ell} \int_0^\infty y \sin \ell y \operatorname{sinc}^n y \,d{y} \right) \lambda^{3}(dW)
\end{equation}
where $\ell = \left\| x \right\|$. Further, any function $g_n \colon \operatorname{VP}_n \rightarrow \mathbb{R}$ which can be expressed in terms of $\mathbf{G}$ as $g_n = g \circ f_0^*$ has 
\begin{equation*}
\operatorname{\mathcal{E}}_{\nu_{\mathbf{G}_n}}\! \left(g_n\right) = \operatorname{\mathcal{E}}_{\nu_{\mathbf{G}}}\! \left(g\right).
\end{equation*}

\label{prop:annihilator props}\ifinner\else\mgp{\raggedright\tiny \ref{prop:annihilator props} prop:annihilator props}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{prop:annihilator props} prop:annihilator props}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{prop:annihilator props} prop:annihilator props}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{prop:annihilator props} prop:annihilator props}\ignorespaces\fi
If we have a map $F \colon U \rightarrow V$, and we take $F^* \colon \operatorname{Hom}(V,W) \rightarrow \operatorname{Hom}(U,W)$ then
\begin{equation*}
\operatorname{im} F^* = (\ker F)^0 \quad\text{and}\quad \ker F^* = (\operatorname{im} F)^0.
\end{equation*}

Suppose $A,B \in \operatorname{Hom}(V,W)$. Then, by definition, 
	\[
		\left< A, B \right>_{\operatorname{Fr}} = \operatorname{tr} A^\dag B,
	\]
	where $A^\dag$ is the adjoint of $A$ with respect to the $\left< -, - \right>_{V,F}$ and $\left< -, - \right>_{W,H}$ inner products. Hence, Lemma~\ref{lem:adjoint formula} implies that
\begin{equation}
		\left< A, B \right>_{\operatorname{Fr}} = \operatorname{tr} A^\dagB = \operatorname{tr} F^{-1} A^T HB = \operatorname{tr} A^T HB F^{-1}  = \left< A, B \right>_{H \otimes F^{-1}}
\label{eq:Frobenius product formulas}\ifinner\else\mgp{\raggedright\tiny \ref{eq:Frobenius product formulas} eq:Frobenius product formulas}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{eq:Frobenius product formulas} eq:Frobenius product formulas}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{eq:Frobenius product formulas} eq:Frobenius product formulas}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{eq:Frobenius product formulas} eq:Frobenius product formulas}\ignorespaces\fi
\end{equation}
	by the cyclic invariance of trace.

\label{def:pseudoinverse}\ifinner\else\mgp{\raggedright\tiny \ref{def:pseudoinverse} def:pseudoinverse}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{def:pseudoinverse} def:pseudoinverse}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{def:pseudoinverse} def:pseudoinverse}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{def:pseudoinverse} def:pseudoinverse}\ignorespaces\fi
If $F \colon U \to V$ is a linear map between inner product spaces, the \emph{Moore--Penrose pseudoinverse} $F^+ \colon V \to U$ is the unique linear map satisfying:
\begin{equation}
F F^+ F = F, \quad F^+ F F^+ = F^+, \quad FF^+ \text{ and } F^+F \text{ are self-adjoint.}
\label{eq:Moore-Penrose conditions}\ifinner\else\mgp{\raggedright\tiny \ref{eq:Moore-Penrose conditions} eq:Moore-Penrose conditions}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \ref{eq:Moore-Penrose conditions} eq:Moore-Penrose conditions}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{eq:Moore-Penrose conditions} eq:Moore-Penrose conditions}\ignorespaces\fi\ifinner\else\mgp{\raggedright\tiny \raggedright\tiny \raggedright\tiny \raggedright\tiny \ref{eq:Moore-Penrose conditions} eq:Moore-Penrose conditions}\ignorespaces\fi
\end{equation}

The proof is an exercise in checking that $(F^+)^*$ satisfies the Moore--Penrose conditions for a pseudoinverse of $F^* \colon \operatorname{Hom}(V,W) \rightarrow \operatorname{Hom}(U,W)$.
\begin{equation*}
(F^+)^* F^* (F^+)^* = (F^+ F F^+)^* = (F^+)^* \quad\text{and}\quad



F^* (F^+)^* F^* = (F F^+ F)^* = F^*.
\end{equation*}
Referring to~Definition~\ref{def:induced inner product} for the Frobenius inner product, and using standard properties of $\dag$ and $*$\footnote{Here we've used several properties of $\dag$ and $\star$: $(FG)^\dag = G^\dag F^\dag$ in the second equality; $F^{*\dag} = F^{\dag*}$ and $(F^+F)^\dag = F^+ F$ in the third, and $(FG)^* = G^* F^*$ in the last one. }
\[
\left< F^*(F^+)^* A, B \right>_{\operatorname{Fr}} = \operatorname{tr} (F^*(F^+)^*A)^\dag B = \operatorname{tr} A^\dag (F^+ F)^{*\dag} B = \operatorname{tr} A^\dag (F^+F)^* B = \left< A, F^* (F^+)^* B \right>_{\operatorname{Fr}},
\]
so $(F^* (F^+)^*)^\dag = (F^* (F^+)^*)$. Similarly, 
\begin{multline*}
\left< (F^+)^* F^* A, B \right>_{\operatorname{Fr}} = \operatorname{tr} ((F^+)^* F^* A)^\dag B = \operatorname{tr} A^\dag ((F^+)^* F^*)^\dag B \\
=\operatorname{tr} A^\dag (F F^+)^{*\dag} B = \operatorname{tr} A^\dag (F F^+)^* B 

= \left< A, (F^+)^* F^* B \right>_{\operatorname{Fr}},
\end{multline*}
so $((F^+)^* F^*)^\dag = (F^+)^* F^*$.
